{
 "didatica": [
  {
   "campo": "resolucao.antes.texto",
   "depois": "O travessão duplo funciona como um par de vírgulas mais forte. Ele isola um trecho colocado no meio da frase, que acrescenta uma informação ou um exemplo. Se você retirar esse trecho, a frase continua completa. A questão pede a função desse trecho, e não a tradução do texto inteiro.",
   "motivo": "Frases mais simples; 'intercalado' e 'ênfase' trocados por palavras do dia a dia."
  },
  {
   "campo": "resolucao.antes.formulas",
   "depois": [
    "— trecho — = inciso: informação extra no meio da frase",
    "oposição seria marcada por but, however; conclusão, por therefore, so",
    "consequência seria marcada por as a result, consequently; proporção, por the more... the more",
    "even = até mesmo (reforça um exemplo surpreendente)"
   ],
   "motivo": "'Pediria' deixava a regra vaga; 'seria marcada por' diz claramente o que cada relação exige."
  },
  {
   "campo": "resolucao.antes.simbolos",
   "depois": [
    ["even giraffes", "até mesmo as girafas"],
    ["species including", "espécies incluindo"],
    ["prefer to work for their food", "preferem trabalhar para obter a comida"],
    ["inciso", "trecho no meio da frase que explica ou acrescenta algo e pode ser retirado sem quebrar a frase"],
    ["esclarecimento", "explicação ou informação que deixa a ideia mais clara"]
   ],
   "motivo": "Definir 'esclarecimento', que é a alternativa correta; 'intercalado' foi trocado por palavras simples."
  },
  {
   "campo": "resolucao.passos[0].conta",
   "depois": "\"primates — even giraffes —\" (primatas, até mesmo girafas)",
   "motivo": "Traz a tradução do trecho citado para a conta."
  },
  {
   "campo": "resolucao.passos[0].porque",
   "depois": "Frase inteira: espécies incluindo aves, roedores, lobos, primatas, até mesmo girafas, preferem trabalhar pela comida. O trecho está no meio de uma lista de animais.",
   "motivo": "Redação mais direta."
  },
  {
   "campo": "resolucao.passos[1].conta",
   "depois": "sem o trecho: a frase segue completa",
   "motivo": "A conta fica mais clara."
  },
  {
   "campo": "resolucao.passos[3].conta",
   "depois": "but? therefore? as a result?",
   "motivo": "Mantida; o porquê é que foi reescrito."
  },
  {
   "campo": "resolucao.passos[3].porque",
